	});

	// C[j][m] = (j * (m + 3) % nl) / (5 * nl)
	traverser(C).for_each([=](auto state) {
		auto [j, m] = get_indices<'j', 'm'>(state);
		C[state] = (num_t)((j * (m + 3) % nl)) / (num_t)(5 * nl);
	});

	// D[m][l] = ((m * (l + 2) + 2) % nk) / (5 * nk)
	traverser(D).for_each([=](auto state) {
		auto [m, l] = get_indices<'m', 'l'>(state);
		D[state] = (num_t)((m * (l + 2) + 2) % nk) / (num_t)(5 * nk);
	});
}

// Main computational kernel: three matrix multiplications
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	using namespace noarr;

#pragma scop
	// E := A * B
	// E: i x j, A: i x k, B: k x j
	traverser(E, A, B).template for_dims<'i'>([=](auto inner) {
		// for each i, zero E(i, j) over all j
		inner.template for_each<'j'>([=](auto state) {
			E[state] = num_t(0);
		});

		// accumulate over k
		inner.for_each([=](auto state) {
			E[state] += A[state] * B[state];
		});
	});

	// F := C * D
	// F: j x l, C: j x m, D: m x l
	traverser(F, C, D).template for_dims<'j'>([=](auto inner) {
		// for each j, zero F(j, l) over all l
		inner.template for_each<'l'>([=](auto state) {
			F[state] = num_t(0);
		});

		// accumulate over m
		inner.for_each([=](auto state) {
			F[state] += C[state] * D[state];
		});
	});

	// G := E * F
	// G: i x l, E: i x j, F: j x l
	traverser(G, E, F).template for_dims<'i'>([=](auto inner) {
		// for each i, zero G(i, l) over all l
		inner.template for_each<'l'>([=](auto state) {
			G[state] = num_t(0);
		});

		// accumulate over j
		inner.for_each([=](auto state) {
			G[state] += E[state] * F[state];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem sizes
	std::size_t ni = NI;
	std::size_t nj = NJ;
