#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "3mm.hpp"

using num_t = DATA_TYPE;

namespace {

// basic 1D dimensions
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto l_vec = noarr::vector<'l'>();
constexpr auto m_vec = noarr::vector<'m'>();

// Tuning / layout specification:
// We follow row-major C layout: for a matrix R x C we use vector<'col'>() ^ vector<'row'>().
struct tuning {
	// E: ni x nj, indexed as E[i][j]
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec);
	// A: ni x nk, indexed as A[i][k]
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: nk x nj, indexed as B[k][j]
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec);
	// F: nj x nl, indexed as F[j][l]
	DEFINE_PROTO_STRUCT(f_layout, l_vec ^ j_vec);
	// C: nj x nm, indexed as C[j][m]
	DEFINE_PROTO_STRUCT(c_layout, m_vec ^ j_vec);
	// D: nm x nl, indexed as D[m][l]
	DEFINE_PROTO_STRUCT(d_layout, l_vec ^ m_vec);
	// G: ni x nl, indexed as G[i][l]
	DEFINE_PROTO_STRUCT(g_layout, l_vec ^ i_vec);
} tuning;

// Array initialization (mirrors the original C init_array)
void init_array(auto A, auto B, auto C, auto D) {
	using namespace noarr;

	// derive sizes from structures
	const std::size_t ni = A | get_length<'i'>();
	const std::size_t nj = B | get_length<'j'>();
	const std::size_t nk = A | get_length<'k'>();
	const std::size_t nl = D | get_length<'l'>();

	// A[i][k] = ((i*k+1) % ni) / (5*ni)
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = static_cast<num_t>((i * k + 1) % ni) /
		           static_cast<num_t>(5 * ni);
	});

	// B[k][j] = ((k*(j+1)+2) % nj) / (5*nj)
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = static_cast<num_t>((k * (j + 1) + 2) % nj) /
		           static_cast<num_t>(5 * nj);
	});

	// C[j][m] = (j*(m+3) % nl) / (5*nl)
	traverser(C).for_each([=](auto state) {
		auto [j, m] = get_indices<'j', 'm'>(state);
		C[state] = static_cast<num_t>((j * (m + 3)) % nl) /
		           static_cast<num_t>(5 * nl);
	});

	// D[m][l] = ((m*(l+2)+2) % nk) / (5*nk)
	traverser(D).for_each([=](auto state) {
		auto [m, l] = get_indices<'m', 'l'>(state);
		D[state] = static_cast<num_t>((m * (l + 2) + 2) % nk) /
		           static_cast<num_t>(5 * nk);
	});
}

// Main computational kernel:
// E := A * B
// F := C * D
// G := E * F
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	using namespace noarr;

#pragma scop
	// -----------------------------------------------------------------
	// E := A * B
	// E[i][j] = sum_{k} A[i][k] * B[k][j]
	// -----------------------------------------------------------------
	traverser(E, A, B).template for_dims<'i'>([=](auto trav_i) {
		// for (j)
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			// state with i and j fixed
			auto state_ij = trav_ij.state();

			// E[i][j] = 0.0;
			E[state_ij] = num_t(0);

			// for (k)
			trav_ij.for_each([=](auto state_ijk) {
				// A: i x k, B: k x j, all aligned by dims 'i','j','k'
				E[state_ij] += A[state_ijk] * B[state_ijk];
			});
		});
	});

	// -----------------------------------------------------------------
	// F := C * D
	// F[j][l] = sum_{m} C[j][m] * D[m][l]
	// (original loops: i over NJ, j over NL, k over NM)
	// -----------------------------------------------------------------
	traverser(F, C, D).template for_dims<'j'>([=](auto trav_j) {
		// for (l)
		trav_j.template for_dims<'l'>([=](auto trav_jl) {
			auto state_jl = trav_jl.state();

			// F[j][l] = 0.0;
			F[state_jl] = num_t(0);

			// for (m)
			trav_jl.for_each([=](auto state_jlm) {
				// C: j x m, D: m x l
				F[state_jl] += C[state_jlm] * D[state_jlm];
			});
		});
	});

	// -----------------------------------------------------------------
	// G := E * F
	// G[i][l] = sum_{j} E[i][j] * F[j][l]
	// (original loops: i over NI, j over NL, k over NJ)
	// -----------------------------------------------------------------
	traverser(G, E, F).template for_dims<'i'>([=](auto trav_i) {
		// for (l)
		trav_i.template for_dims<'l'>([=](auto trav_il) {
			auto state_il = trav_il.state();

			// G[i][l] = 0.0;
			G[state_il] = num_t(0);

			// for (j)
			trav_il.for_each([=](auto state_ilj) {
				// E: i x j, F: j x l
				G[state_il] += E[state_ilj] * F[state_ilj];
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

	// set all relevant lengths once
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl) ^
		noarr::set_length<'m'>(nm);

	// allocate bags for all matrices
	auto E = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);
	auto F = noarr::bag(noarr::scalar<num_t>() ^ tuning.f_layout ^ set_lengths);
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto D = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout ^ set_lengths);
	auto G = noarr::bag(noarr::scalar<num_t>() ^ tuning.g_layout ^ set_lengths);

	// initialize input arrays A, B, C, D
	init_array(A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_3mm(E.get_ref(), A.get_ref(), B.get_ref(),
	           F.get_ref(), C.get_ref(), D.get_ref(), G.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (G) in a stable, layout-agnostic way
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' so rows are contiguous in output
		noarr::serialize_data(std::cerr, G.get_ref() ^ noarr::hoist<'i'>());
	}

	// print elapsed time in seconds
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
